import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const c=JSON.parse('{"title":"Συμβάντα webhook πληρωμών","description":"","frontmatter":{},"headers":[],"relativePath":"el/developers/webhook-events.md","filePath":"el/developers/webhook-events.md"}'),d={name:"el/developers/webhook-events.md"};function s(h,t,n,l,p,i){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="συμβαντα-webhook-πληρωμων" tabindex="-1">Συμβάντα webhook πληρωμών <a class="header-anchor" href="#συμβαντα-webhook-πληρωμων" aria-label="Permalink to &quot;Συμβάντα webhook πληρωμών&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Προσχέδιο βάσει πηγαίου κώδικα · v0.7.9. Επιβεβαιώστε διαθεσιμότητα και δικαιώματα στην εγκεκριμένη έκδοση.</p></div><h2 id="επιστροφες-συμβαντων-παροχου" tabindex="-1">Επιστροφές συμβάντων παρόχου <a class="header-anchor" href="#επιστροφες-συμβαντων-παροχου" aria-label="Permalink to &quot;Επιστροφές συμβάντων παρόχου&quot;">​</a></h2><p>Ο κώδικας διαθέτει <code>POST /api/v1/webhooks/payments/:provider</code>. Η διαδρομή αυτή διαφέρει από το API χειριστή με bearer token. Ελέγχει την υπογραφή παρόχου στο αρχικό σώμα αιτήματος και απαιτεί εξωτερικό αναγνωριστικό συμβάντος.</p><table tabindex="0"><thead><tr><th>Απόκριση</th><th>Ερμηνεία</th></tr></thead><tbody><tr><td>400</td><td>Απουσία αρχικού σώματος ή ID συμβάντος</td></tr><tr><td>401</td><td>Μη έγκυρη υπογραφή webhook</td></tr><tr><td>503</td><td>Μη ρυθμισμένο μυστικό webhook</td></tr><tr><td>200</td><td>Αποδοχή ή επιβεβαίωση διπλού συμβάντος</td></tr><tr><td>500</td><td>Αποτυχία επεξεργασίας</td></tr></tbody></table><p>Ο χειριστής καταγράφει συμβάντα με το ID παρόχου και αποτύπωμα περιεχομένου. Η επιβεβαίωση διπλού συμβάντος δεν αποτελεί δεύτερη πληρωμή. Ελέγξτε το ιστορικό συμφωνίας και την κατάσταση επεξεργασίας πριν ερμηνεύσετε την αποδοχή ως οικονομικό αποτέλεσμα.</p><p>Χρησιμοποιήστε επαληθευμένες οδηγίες υπογραφής του παρόχου και εγκεκριμένα δοκιμαστικά δεδομένα. Μην καταγράφετε μυστικά webhook ή πραγματικά στοιχεία καρτών και μην παρακάμπτετε την επαλήθευση.</p><p>Δείτε <a href="/el/integrations/payment-providers.html">Πάροχοι πληρωμών</a>.</p>',8)])])}const _=e(d,[["render",s]]);export{c as __pageData,_ as default};
